17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
29	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.util.StringUtils;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    /**
71	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
72	     * and a domain containing at least one dot, with no whitespace in any segment.
73	     */
74	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        validateRequiredFields(ownerFieldsDto);
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
118	        requireUniqueTelephone(telephone);
119	        owner.setTelephone(telephone);
120	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
121	        this.clinicService.saveOwner(owner);
122	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
123	        headers.setLocation(UriComponentsBuilder.newInstance()
124	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
125	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
126	    }
127	
128	    /**
129	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
130	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
131	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
132	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
133	     *
134	     * @param ownerFieldsDto the submitted owner fields
135	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
136	     */
137	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
138	        List<String> invalidFields = new ArrayList<>();
139	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
140	            invalidFields.add("firstName");
141	        }
142	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
143	            invalidFields.add("lastName");
144	        }
145	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
146	            invalidFields.add("address");
147	        }
148	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
149	            invalidFields.add("city");
150	        }
151	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
152	            invalidFields.add("telephone");
153	        }
154	        if (!invalidFields.isEmpty()) {
155	            throw new InvalidOwnerFieldsException(invalidFields);
156	        }
157	    }
158	
159	    /**
160	     * Normalizes a submitted telephone number by removing every non-digit character and requires the
161	     * result to contain exactly 10 digits. The normalized 10-digit value is what gets stored and
162	     * returned.
163	     *
164	     * @param telephone the raw telephone value from the request
165	     * @return the normalized 10-digit telephone number
166	     * @throws InvalidOwnerFieldsException if the value does not contain exactly 10 digits after stripping
167	     */
168	    private String normalizeTelephone(String telephone) {
169	        String digits = digitsOf(telephone);
170	        if (digits.length() != 10) {
171	            throw new InvalidOwnerFieldsException(List.of("telephone"));
172	        }
173	        return digits;
174	    }
175	
176	    /**
177	     * Strips every non-digit character from a telephone value, giving the single authoritative
178	     * definition of a telephone's normalized digit form. Unlike {@link #normalizeTelephone(String)}
179	     * this performs no length validation, so it is safe to apply to already-stored (possibly legacy)
180	     * values when comparing them.
181	     *
182	     * @param telephone the raw telephone value, possibly {@code null}
183	     * @return the value's digits, or the empty string if {@code null}
184	     */
185	    private String digitsOf(String telephone) {
186	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
187	    }
188	
189	    /**
190	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
191	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
192	     * and returned lower-cased.
193	     *
194	     * @param email the raw email value from the request, possibly {@code null}
195	     * @return the lower-cased email, or {@code null} when none was supplied
196	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
197	     */
198	    private String normalizeEmail(String email) {
199	        if (!StringUtils.hasText(email)) {
200	            return null;
201	        }
202	        String trimmed = email.trim();
203	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
204	            throw new InvalidOwnerFieldsException(List.of("email"));
205	        }
206	        return trimmed.toLowerCase(Locale.ROOT);
207	    }
208	
209	    /**
210	     * Rejects a telephone number that, once normalized to its digits, is already used by an existing
211	     * owner. This enforces that no two owners share the same normalized telephone.
212	     *
213	     * @param telephone the normalized (digits-only) telephone of the owner being created
214	     * @throws DuplicateTelephoneException if another owner already has this normalized telephone
215	     */
216	    private void requireUniqueTelephone(String telephone) {
217	        boolean inUse = this.clinicService.findAllOwners().stream()
218	            .map(Owner::getTelephone)
219	            .filter(existing -> existing != null)
220	            .map(this::digitsOf)
221	            .anyMatch(telephone::equals);
222	        if (inUse) {
223	            throw new DuplicateTelephoneException(telephone);
224	        }
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
230	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
231	        if (currentOwner == null) {
232	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	        }
234	        currentOwner.setAddress(ownerFieldsDto.getAddress());
235	        currentOwner.setCity(ownerFieldsDto.getCity());
236	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
237	        currentOwner.setLastName(ownerFieldsDto.getLastName());
238	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
239	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
240	        this.clinicService.saveOwner(currentOwner);
241	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Transactional
246	    @Override
247	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        this.clinicService.deleteOwner(owner);
253	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
254	    }
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner == null) {
261	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	        }
263	        HttpHeaders headers = new HttpHeaders();
264	        Pet pet = petMapper.toPet(petFieldsDto);
265	        owner.setId(ownerId);
266	        pet.setOwner(owner);
267	        pet.getType().setName(null);
268	        this.clinicService.savePet(pet);
269	        PetDto petDto = petMapper.toPetDto(pet);
270	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
271	            .buildAndExpand(pet.getId()).toUri());
272	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
273	    }
274	
275	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
276	    @Override
277	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
278	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
279	        if (currentOwner != null) {
280	            Pet currentPet = this.clinicService.findPetById(petId);
281	            if (currentPet != null) {
282	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
283	                currentPet.setName(petFieldsDto.getName());
284	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
285	                this.clinicService.savePet(currentPet);
286	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
287	            }
288	        }
289	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
290	    }
291	
292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Override
294	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
295	        HttpHeaders headers = new HttpHeaders();
296	        Visit visit = visitMapper.toVisit(visitFieldsDto);
297	        Pet pet = new Pet();
298	        pet.setId(petId);
299	        visit.setPet(pet);
300	        this.clinicService.saveVisit(visit);
301	        VisitDto visitDto = visitMapper.toVisitDto(visit);
302	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
303	            .buildAndExpand(visit.getId()).toUri());
304	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
305	    }
306	
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
311	        Owner owner = this.clinicService.findOwnerById(ownerId);
312	        if (owner != null) {
313	            Pet pet = owner.getPet(petId);
314	            if (pet != null) {
315	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
316	            }
317	        }
